import{_ as e,o as i,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2020-04-22 :: Ceph Docubetter Meeting","description":"","frontmatter":{"title":"2020-04-22 :: Ceph Docubetter Meeting","date":"2020-04-22T00:00:00.000Z","updated":"2020-04-30T00:00:00.000Z","tags":["Ceph文档更新","Google Season of Docs","Ceph网站改进","信息检索倡议","Ceph社区"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-04-22_-_-_Ceph_Docubetter_Meeting.md","filePath":"posts/2020/2020-04-22_-_-_Ceph_Docubetter_Meeting.md","lastUpdated":1780460162000}'),a={name:"posts/2020/2020-04-22_-_-_Ceph_Docubetter_Meeting.md"};function r(s,l,n,h,p,u){return i(),o("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Zack</li><li>会议主持人</li></ul><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：未提及具体日期</li><li>时长：未明确记录</li></ul><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><ol><li><p><strong>疫情更新</strong></p><ul><li>澳大利亚疫情控制良好，连续两天无新增病例和死亡病例。</li><li>讨论了澳大利亚与美国的疫情管理差异，对澳大利亚的疫情控制表示赞赏。</li></ul></li><li><p><strong>工作更新</strong></p><ul><li>Zack在欧洲时间工作，与Sebastian合作处理orchestrator box bugs。</li><li>提到了长时间工作（17小时）的经历，以及对工作的热情和享受。</li></ul></li><li><p><strong>Ceph文档更新</strong></p><ul><li>讨论了Ceph文档的当前状态，特别是ceph.com和seba/install网站的问题。</li><li>提到了文档中的403和404错误，以及需要解决这些问题的紧迫性。</li><li>讨论了将文档迁移到readthedocs的计划，并处理冗余的网站。</li></ul></li><li><p><strong>信息检索倡议</strong></p><ul><li>提出了一个信息检索倡议，旨在改进文档的可发现性和可用性。</li><li>讨论了使用Sphinx和 restructured text来创建更好的文档索引。</li><li>强调了文档编写和版本控制的复杂性，并寻求简化这些流程。</li></ul></li><li><p><strong>Google Season of Docs</strong></p><ul><li>讨论了参与Google Season of Docs的计划，特别是关于初学者指南的项目。</li><li>提到了提交截止日期（5月4日），并计划提前准备和审查提案。</li></ul></li><li><p><strong>Ceph网站改进</strong></p><ul><li>讨论了改进ceph.io网站的必要性，包括简化用户和开发者的导航。</li><li>提到了添加视频和其他多媒体内容的可能性，以提高用户体验。</li></ul></li><li><p><strong>行动计划</strong></p><ul><li>计划在论坛中提出关于ceph.io网站改进的讨论，并创建相关的Trello卡片。</li><li>计划在Google Season of Docs截止日期前准备好提案，并提前进行审查。</li><li>继续跟踪和解决Ceph文档中的问题，特别是403和404错误。</li></ul></li></ol><h4 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h4><ul><li>在论坛中提出关于ceph.io网站改进的讨论。</li><li>准备并审查Google Season of Docs的提案，确保在截止日期前提交。</li><li>继续跟踪和解决Ceph文档中的问题，特别是403和404错误。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议内容主要涉及Ceph文档和网站的改进，以及Google Season of Docs的参与计划。</li><li>讨论了疫情对工作和生活的影响，以及对澳大利亚疫情控制的赞赏。</li><li>强调了信息检索和文档可用性的重要性，以及Ceph社区的合作与贡献。</li></ul>',11)])])}const d=e(a,[["render",r]]);export{_ as __pageData,d as default};
